describe('Image Responsive Scale Test', () => {
  beforeEach(() => {
    cy.visit('/images');
  });

  it('should scale images down to fit screen width on mobile devices', () => {
    // Setup: Open the images page
    cy.get('[data-testid="images-list"]').should('be.visible');

    // Verify initial state: images are displayed at full size
    cy.get('[data-testid="image-item"]').first().should('be.visible');
    cy.get('[data-testid="image-item"]').first().should('have.css', 'width', '100%');

    // Intercept API call to load images
    cy.intercept('GET', '/api/images').as('loadImages');

    // Trigger image load
    cy.get('[data-testid="load-more-button"]').click();
    cy.wait('@loadImages');

    // Verify images are now scaled down
    cy.get('[data-testid="image-item"]').first().should('have.css', 'width', '50%');
    cy.get('[data-testid="image-item"]').first().should('have.css', 'height', 'auto');

    // Verify image aspect ratio is maintained
    cy.get('[data-testid="image-item"]').first().should('have.css', 'aspect-ratio', '1/1');

    // Verify image is still visible and not distorted
    cy.get('[data-testid="image-item"]').first().should('be.visible');
    cy.get('[data-testid="image-item"]').first().should('not.contain', 'loading');

    // Verify image source is still correct
    cy.get('[data-testid="image-item"]').first().should('have.attr', 'src');
  });

  it('should handle edge case: images with very large dimensions', () => {
    // Setup: Open the images page
    cy.get('[data-testid="images-list"]').should('be.visible');

    // Intercept API call to load images
    cy.intercept('GET', '/api/images').as('loadImages');

    // Trigger image load
    cy.get('[data-testid="load-more-button"]').click();
    cy.wait('@loadImages');

    // Verify large image is scaled down appropriately
    cy.get('[data-testid="image-item"]').first().should('have.css', 'width', '50%');
    cy.get('[data-testid="image-item"]').first().should('have.css', 'height', 'auto');

    // Verify aspect ratio is maintained
    cy.get('[data-testid="image-item"]').first().should('have.css', 'aspect-ratio', '1/1');

    // Verify image is not stretched or squished
    cy.get('[data-testid="image-item"]').first().should('not.contain', 'stretched');
    cy.get('[data-testid="image-item"]').first().should('not.contain', 'squished');

    // Verify image is still visible and not distorted
    cy.get('[data-testid="image-item"]').first().should('be.visible');
    cy.get('[data-testid="image-item"]').first().should('not.contain', 'loading');

    // Verify image source is still correct
    cy.get('[data-testid="image-item"]').first().should('have.attr', 'src');
  });
});
